const scriptPolicy=window.trustedTypes.createPolicy("webui-test-script",{createHTML:()=>"",createScriptURL:urlString=>{const url=new URL(urlString);if(url.protocol==="chrome:"){return urlString}console.error(`Invalid test URL ${urlString} found.`);return""},createScript:()=>""});function loadScript(url){return new Promise(((resolve,reject)=>{const script=document.createElement("script");script.type="module";script.src=scriptPolicy.createScriptURL(url);script.onerror=function(){reject(new Error(`test_loader_util: Failed to load ${url}`))};script.onload=function(){resolve()};document.body.appendChild(script)}))}export async function loadTestModule(){const params=new URLSearchParams(window.location.search);const module=params.get("module");if(!module){return Promise.resolve(false)}const host=params.get("host")||"webui-test";if(host!=="test"&&host!=="webui-test"){return Promise.reject(new Error(`Invalid host=${host} parameter`))}await loadScript(`chrome://${host}/${module}`);return Promise.resolve(true)}export async function loadMochaAdapter(){const params=new URLSearchParams(window.location.search);const adapter=params.get("adapter")||"mocha_adapter.js";if(!["mocha_adapter.js","mocha_adapter_simple.js"].includes(adapter)){return Promise.reject(new Error(`Invalid adapter=${adapter} parameter`))}await loadScript(`chrome://webui-test/${adapter}`);return Promise.resolve(true)}